source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Connect aligned pairs of identical non-background markers through intervening cells.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(x == v for row in grid for x in row))
    for r in range(h):
        for c1 in range(w):
            for c2 in range(c1 + 1, w):
                if grid[r][c1] == grid[r][c2] != bg and all(grid[r][c] == bg for c in range(c1+1,c2)):
                    for c in range(c1+1,c2): out[r][c] = 3
    for c in range(w):
        for r1 in range(h):
            for r2 in range(r1 + 1, h):
                if grid[r1][c] == grid[r2][c] != bg and all(grid[r][c] == bg for r in range(r1+1,r2)):
                    for r in range(r1+1,r2): out[r][c] = 3
    return out
'''
